export const LEGACY_UNIT_MAP = new Map<string, LegacyUnitRecord>(
  LEGACY_UNIT_INVENTORY.map((u) => [u.legacyId, u]),
);

export function getLegacyUnitInfo(id: string): LegacyUnitRecord | undefined {
  if (!id) return undefined;
  return LEGACY_UNIT_MAP.get(id.toLowerCase().trim());
}

export function isLegacyUnitId(id: string): boolean {
  if (!id) return false;
  return LEGACY_UNIT_MAP.has(id.toLowerCase().trim());
}

